},
setPropertyAsAUTF8String(name, value) {
  this.setProperty(name, value);
},
setPropertyAsUint32(name, value) {
  this.setProperty(name, value);
},
setPropertyAsBool(name, value) {
  this.setProperty(name, value ? "1" : "0");
},
deleteProperty(name) {
  this._properties.delete(name);
